17	public class TorqueRepository {
18	
19	    private final JdbcTemplate jdbcTemplate;
20	
21	    public TorqueRepository(JdbcTemplate jdbcTemplate) {
22	        this.jdbcTemplate = jdbcTemplate;
23	    }
24	
25	    /** 力矩记录行。 */
26	    public record TorqueRow(
27	            long id,
28	            long cardId,
29	            long fastenerId,
30	            int attemptNo,
31	            BigDecimal measuredTorque,
32	            BigDecimal deviationPct,
33	            boolean inTolerance,
