41	    public record ReworkRow(
42	            long id,
43	            long cardId,
44	            long fastenerId,
45	            int reworkNo,
46	            String requestId,
47	            String reason,
48	            Instant createdAt) {
49	    }
50	
51	    private static final RowMapper<TorqueRow> TORQUE_MAPPER = (rs, n) -> new TorqueRow(
52	            rs.getLong("id"),
53	            rs.getLong("card_id"),
54	            rs.getLong("fastener_id"),
55	            rs.getInt("attempt_no"),
56	            rs.getBigDecimal("measured_torque"),
57	            rs.getBigDecimal("deviation_pct"),
58	            rs.getInt("in_tolerance") == 1,
59	            rs.getString("operator"),
60	            rs.getString("tool_code"),
61	            rs.getTimestamp("measured_at").toInstant(),
62	            rs.getString("request_id"));
