98	                        + "measured_at, request_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
99	                cardId, pointCode, measuredTorque, operator, toolCode,
100	                Timestamp.from(measuredAt), requestId, Timestamp.from(measuredAt));
101	    }
