20	 */
21	class ConcurrentDispatchServiceTest extends AbstractServiceTest {
22	
23	    @Autowired
24	    private OperationService service;
25	
26	    @Test
27	    @DisplayName("同一工位 8 个线程并发派工不同工序卡：恰 1 张受理，其余 409，最终仅 1 张执行中卡")
28	    void concurrentDispatchSingleAcceptance() throws InterruptedException {
29	        int threads = 8;
30	        ExecutorService pool = Executors.newFixedThreadPool(threads);
31	        CountDownLatch ready = new CountDownLatch(threads);
32	        CountDownLatch start = new CountDownLatch(1);
33	        AtomicInteger accepted = new AtomicInteger();
34	        AtomicInteger rejected = new AtomicInteger();
35	        AtomicInteger other = new AtomicInteger();
36	
37	        try {
38	            for (int i = 0; i < threads; i++) {
39	                final int index = i;
40	                pool.submit(() -> {
41	                    ready.countDown();
42	                    try {
43	                        start.await();
44	                        Outcome outcome = service.dispatch(TestRequests.singlePoint(
45	                                "req-conc-" + index, "CARD-C" + index, "STATION-X", "N",
46	                                "P1", "100.000"));
47	                        if (outcome.status() == 201) {
48	                            accepted.incrementAndGet();
49	                        } else if (outcome.status() == 409) {
50	                            rejected.incrementAndGet();
51	                        } else {
52	                            other.incrementAndGet();
53	                        }
54	                    } catch (Exception e) {
55	                        other.incrementAndGet();
56	                    }
57	                });
58	            }
59	            assertThat(ready.await(5, TimeUnit.SECONDS)).isTrue();
60	            start.countDown();
61	        } finally {
62	            pool.shutdown();
63	            assertThat(pool.awaitTermination(15, TimeUnit.SECONDS)).isTrue();
64	        }
65	
66	        assertThat(other.get()).isZero();
67	        assertThat(accepted.get()).isEqualTo(1);
68	        assertThat(rejected.get()).isEqualTo(threads - 1);
69	
70	        Integer guardCount = jdbcTemplate.queryForObject(
71	                "SELECT COUNT(*) FROM station_guard WHERE station = ?", Integer.class, "STATION-X");
72	        assertThat(guardCount).isEqualTo(1);
73	    }
74	
75	    @Test
76	    @DisplayName("同一 requestId 并发重复派工：只产生一张卡，两个调用都返回首次 201")
77	    void concurrentSameRequestId() throws InterruptedException {
78	        int threads = 4;
79	        ExecutorService pool = Executors.newFixedThreadPool(threads);
80	        CountDownLatch ready = new CountDownLatch(threads);
81	        CountDownLatch start = new CountDownLatch(1);
82	        AtomicInteger ok = new AtomicInteger();
83	        AtomicInteger conflict = new AtomicInteger();
84	        AtomicInteger other = new AtomicInteger();
85	
86	        try {
