    @Test
    @DisplayName("乱序缓冲：先到 2 号包仅缓冲不消费，补齐 1 号后按前缀连续入账")
    void outOfOrderBufferThenConsume() {
        prepareSession("SES-U2", "CARD-U2", "S-U2");

        // 2 号先到：缓冲，水位线不动，不产生力矩记录
        CollectionUploadResult buffered = upload("u-o1", "SES-U2", 1,
