    @Test
    @DisplayName("超窗整批拒绝：水位线 0 时 21 号包 422，同批有效 1 号也不写入")
    void windowExceededRejectsWholeBatch() {
        prepareSession("SES-U3", "CARD-U3", "S-U3");

        assertThatThrownBy(() -> collectionService.upload(TestRequests.upload(
                "u-w1", "SES-U3", 1,
