        // 正确版本继续成功
        CollectionUploadResult ok = upload("u-v3", "SES-U7", 2,
                TestRequests.packet(2, "P2", "50.000", "2026-09-26T01:01:00Z"));
        assertThat(ok.version()).isEqualTo(3);
