        // 归档后上传 2 号包：只记迟到
        CollectionUploadResult late = upload("u-k5-late", "SES-K5", 3, 2, "105.000",
                "2026-09-26T01:05:00Z");
        assertThat(late.late()).isTrue();
        assertThat(late.cardStatus()).isEqualTo("ARCHIVED");
        assertThat(late.watermark()).isEqualTo(1);
